OUT_DIR = os.path.dirname(os.path.abspath(__file__))

for name, svg in ICONS.items():
    png_path = os.path.join(OUT_DIR, f"{name}.png")
    cairosvg.svg2png(bytestring=svg.encode("utf-8"), write_to=png_path, output_width=24, output_height=24)
    print(f"  OK {name}.png")

print(f"\nAll {len(ICONS)} icons saved to {OUT_DIR}")
